# -*- coding: utf-8 -*-
"""从前端引擎生成器：由 rules_definition.json 自动生成 patient_ui/engine.js。

评审 P0-2：医疗分级不允许存在两套会漂移的规则。前端不再手工维护 JS 分级逻辑，
每次规则变更后运行本脚本重新生成：

    python generate_frontend_engine.py

生成物带 ENGINE_BUILD（规则文件的 SHA-256），index.html 会显示该指纹以便核对。
"""

import hashlib
import json
from datetime import datetime, timezone
from pathlib import Path

HERE = Path(__file__).resolve().parent
DEF_PATH = HERE / "rules_definition.json"
OUT_PATH = HERE.parent / "patient_ui" / "engine.js"

TEMPLATE = """\
/* =========================================================================
 * AUTO-GENERATED by rule_engine/generate_frontend_engine.py
 * Source of truth: rule_engine/rules_definition.json
 * BUILD: __BUILD__
 * GENERATED AT: __GENERATED_AT__
 *
 * DO NOT EDIT THIS FILE BY HAND. 规则变更请修改 rules_definition.json 后重新生成。
 * 离线演示用镜像引擎；正式部署时通过 ASSESS_ENDPOINT 调用后端 rule_engine.assess()。
 * ========================================================================= */
(function (global) {
  'use strict';

  var DEF = __DEF_JSON__;

  var HIGH_RISK = DEF.high_risk_overdose_meds;
  var TIMEOUT_MS = 2000;
  var NEGATION = new RegExp(DEF.negation_tokens, 'i');
  var UNCERTAINTY = new RegExp(DEF.uncertainty_patterns, 'gi');
  var NEG_WINDOW = DEF.negation_window || 32;
  var STOP_RE = new RegExp(DEF.stop_tokens || 'stopped', 'i');
  var STOP_WINDOW = DEF.stop_window || 12;
  var BSC = String.fromCharCode(92);
  var NEG_WORD = new RegExp('(?:无|没|不|未|否认|排除)|' + BSC + 'b(?:denies|denied|deny|without|never|no|not)' + BSC + 'b', 'gi');
  var SCOPE_PUNCT = /[,;.!?，。；！？]/;
  var SCOPE_BUT = /\\b(?:but|however|though)\\b/i;
  var LATIN_FILLER = /^[\\sa-z\\ss'\\s-]*$/i;
  var TOLERATE_RE = /\\b(?:tolerate|tolerated|tolerates|tolerance)\\b|耐受/i;

  function isNegated(negScan, start) {
    // 否定作用域：否定词 + 虚词/严重度词 + 症状；标点或 but/however 截断
    var pre = negScan.slice(Math.max(0, start - NEG_WINDOW), start);
    var hits = [];
    var m;
    NEG_WORD.lastIndex = 0;
    while ((m = NEG_WORD.exec(pre)) !== null) {
      hits.push(m);
      if (NEG_WORD.lastIndex === m.index) NEG_WORD.lastIndex++;
    }
    for (var i = hits.length - 1; i >= 0; i--) {
      var filler = pre.slice(hits[i].index + hits[i][0].length);
      if (SCOPE_PUNCT.test(filler) || SCOPE_BUT.test(filler)) continue;
      if (/^[a-z]/i.test(hits[i][0])) {
        if (LATIN_FILLER.test(filler)) return true;      // 英文：否定词+虚词直达症状
      } else {
        if (filler.length <= 4) return true;             // 中文：紧邻 ≤4 字符
      }
    }
    return false;
  }

  var SYM_PATTERNS = DEF.symptom_patterns.map(function (p) {
    return { re: new RegExp(p.re, 'gi'), codes: p.codes, exempt: !!p.negation_exempt };
  });
  var MED_PATTERNS = DEF.med_patterns.map(function (p) {
    return { re: new RegExp(p.re, 'i'), med: p.med };
  });

  function extract(text) {
    var cleaned = String(text || '').replace(/\\s+/g, ' ').trim();
    var negScan = cleaned.replace(UNCERTAINTY, '');
    var symptoms = {};
    var meds = {};
    SYM_PATTERNS.forEach(function (p) {
      p.re.lastIndex = 0;
      var m;
      while ((m = p.re.exec(cleaned)) !== null) {
        if (!p.exempt) {
          if (isNegated(negScan, m.index)) { if (p.re.lastIndex === m.index) p.re.lastIndex++; continue; }
          if (STOP_RE.test(negScan.slice(m.index + m[0].length, m.index + m[0].length + STOP_WINDOW))) {
            if (p.re.lastIndex === m.index) p.re.lastIndex++; continue;
          }
        }
        p.codes.forEach(function (c) { symptoms[c] = true; });
        if (p.re.lastIndex === m.index) p.re.lastIndex++;
      }
    });
    Object.keys(DEF.code_overrides || {}).forEach(function (keep) {
      if (symptoms[keep]) {
        (DEF.code_overrides[keep].removes || []).forEach(function (rm) { delete symptoms[rm]; });
      }
    });
    MED_PATTERNS.forEach(function (p) {
      if (p.re.test(cleaned)) meds[p.med] = true;
    });
    return { symptoms: symptoms, meds: meds };
  }

  function anyIn(list, bag) { return list.some(function (x) { return !!bag[x]; }); }

  function condMatch(rule, symptoms, meds, age) {
    if (rule.symptoms_any && !anyIn(rule.symptoms_any, symptoms)) return false;
    if (rule.symptoms_exactly) {
      var want = {}; rule.symptoms_exactly.forEach(function (c) { want[c] = true; });
      var same = Object.keys(symptoms).length === rule.symptoms_exactly.length &&
        rule.symptoms_exactly.every(function (c) { return symptoms[c]; });
      if (!same) return false;
    }
    if (rule.age_min != null && (age == null || age < rule.age_min)) return false;
    if (rule.requires_any && Object.keys(symptoms).length === 0) return false;
    if (rule.meds_any && !anyIn(rule.meds_any, meds)) return false;
    if (rule.branch_or) {
      var hitMeds = anyIn(rule.branch_or.meds_any || [], meds);
      var hitSym = anyIn(rule.branch_or.symptoms_any || [], symptoms);
      if (!hitMeds && !hitSym) return false;
    }
    return true;
  }

  function validateInput(payload) {
    var errors = [];
    var out = { age: null, symptom_text: '', symptoms: {}, meds: {} };
    if (payload == null || typeof payload !== 'object') {
      errors.push('payload_not_object');
      return { input: out, errors: errors };
    }
    var age = payload.age;
    if (age == null) { out.age = null; }
    else if (typeof age === 'number' && isFinite(age)) {
      if (age >= 0 && age <= 120) out.age = Math.floor(age);
      else errors.push('age_out_of_range:' + age);
    } else if (typeof age === 'string' && /^\\s*\\d+\\s*$/.test(age)) {
      var v = parseInt(age, 10);
      if (v >= 0 && v <= 120) out.age = v; else errors.push('age_out_of_range:' + age);
    } else { errors.push('age_not_numeric'); }

    var text = payload.symptom_text;
    if (text == null) out.symptom_text = '';
    else if (typeof text === 'string') out.symptom_text = text;
    else { errors.push('symptom_text_not_string'); out.symptom_text = String(text); }

    ['symptoms', 'meds_involved'].forEach(function (key) {
      var val = payload[key];
      var target = key === 'symptoms' ? out.symptoms : out.meds;
      if (val == null) return;
      if (Array.isArray(val)) {
        val.forEach(function (v) { if (typeof v === 'string') target[v] = true; });
      } else { errors.push(key + '_not_array'); }
    });
    ['allergies', 'planned_med'].forEach(function (key) {
      var val = payload[key];
      if (val == null) { out[key] = ''; }
      else if (typeof val === 'string') { out[key] = val; }
      else { errors.push(key + '_not_string'); out[key] = String(val); }
    });
    return { input: out, errors: errors };
  }

  function allergyCheck(input) {
    var findings = [];
    var allergyText = ((input.allergies || '') + ' ' + (input.symptom_text || '')).replace(/\s+/g, ' ').trim();
    var negScan = allergyText.replace(UNCERTAINTY, '');
    (DEF.allergy_rules || []).forEach(function (ar) {
      var aRe = new RegExp(ar.allergy_re, 'gi');
      var tRe = new RegExp(ar.trigger_re, 'i');
      var present = false, m;
      aRe.lastIndex = 0;
      while ((m = aRe.exec(negScan)) !== null) {
        if (!isNegated(negScan, m.index) && !TOLERATE_RE.test(negScan.slice(Math.max(0, m.index - 16), m.index))) {
          present = true; break;
        }
        if (aRe.lastIndex === m.index) aRe.lastIndex++;
      }
      if (!present) return;
      var triggerScan = (input.symptom_text || '').replace(aRe, '') + ' ' + (input.planned_med || '');
      if (tRe.test(triggerScan)) findings.push({ allergy: ar.allergy, action: 'stop_planned_medication' });
    });
    return findings;
  }

  function assess(payload) {
    var t0 = Date.now();
    var deadline = t0 + TIMEOUT_MS;
    var vc = validateInput(payload);
    var age = vc.input.age, text = vc.input.symptom_text;
    var symptoms = Object.assign({}, vc.input.symptoms);
    var meds = Object.assign({}, vc.input.meds);

    try {
      if (text) {
        var ex = extract(text);
        Object.assign(symptoms, ex.symptoms);
        Object.assign(meds, ex.meds);
        if (Date.now() > deadline) throw new Error('timeout');
      }
      var hits = [];
      var topTier = '';
      for (var i = 0; i < DEF.rules.length; i++) {
        if (Date.now() > deadline) throw new Error('timeout');
        var rule = DEF.rules[i];
        if (condMatch(rule, symptoms, meds, age)) {
          if (!hits.length) topTier = rule.tier;
          hits.push({ rule_id: rule.id, rule_name: rule.name, evidence: Object.keys(symptoms).sort() });
        }
      }
      var tier, missing = [];
      if (age == null && vc.errors.indexOf('age_not_numeric') < 0 && vc.errors.join('').indexOf('age_out_of_range') < 0) missing.push('age');
      if (Object.keys(symptoms).length === 0 && hits.length === 0) missing.push('symptoms');
      if (!hits.length) {
        if (text.trim().length >= 4 && missing.length === 0) {
          tier = 'medium';
          hits.push({ rule_id: 'R20-MD-99', rule_name: '未命中规则的有主诉病例（保守默认）', evidence: ['default_medium_guard'] });
        } else {
          tier = 'insufficient_info';
          hits.push({ rule_id: 'R99-II-00', rule_name: '信息不足，禁止自动判低', evidence: missing.length ? missing : ['empty_input'] });
        }
      } else { tier = topTier; }

      var findings = allergyCheck(vc.input);
      return {
        tier: tier,
        navigation: DEF.tiers[tier],
        triggered_rules: hits,
        llm_override_allowed: false,
        llm_may_escalate_only: true,
        missing_fields: missing,
        fallback_used: false,
        rules_version: DEF.version + ' (' + DEF.date + ')',
        audit_id: 'fe-' + Math.random().toString(16).slice(2, 10),
        input_errors: vc.errors,
        allergy_conflict: findings.length > 0,
        allergy_findings: findings,
        latency_ms: Date.now() - t0
      };
    } catch (e) {
      return {
        tier: 'high', navigation: DEF.tiers.high,
        triggered_rules: [{ rule_id: 'R98-FB-97', rule_name: '引擎异常保守回退', evidence: [String(e && e.message || e)] }],
        llm_override_allowed: false, llm_may_escalate_only: true,
        missing_fields: [], fallback_used: true,
        rules_version: DEF.version + ' (' + DEF.date + ')',
        audit_id: 'fe-' + Math.random().toString(16).slice(2, 10),
        input_errors: vc.errors,
        allergy_conflict: false, allergy_findings: [],
        latency_ms: Date.now() - t0
      };
    }
  }

  global.TriageEngine = {
    version: DEF.version,
    build: '__BUILD__',
    assess: assess
  };
})(typeof window !== 'undefined' ? window : globalThis);
"""


def main() -> None:
    raw = DEF_PATH.read_bytes()
    sha = hashlib.sha256(raw).hexdigest()
    defn = json.loads(raw.decode("utf-8"))

    js = (
        TEMPLATE
        .replace("__BUILD__", f"sha256:{sha[:16]}")
        .replace("__GENERATED_AT__", datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%MZ"))
        .replace("__DEF_JSON__", json.dumps(defn, ensure_ascii=False))
    )
    OUT_PATH.write_text(js, encoding="utf-8", newline="\n")
    print(f"OK -> {OUT_PATH}")
    print(f"rules: {defn['version']} build=sha256:{sha[:16]} size={len(js)/1024:.1f}KB")


if __name__ == "__main__":
    main()
